function windLevel(constant, gust) {
  if (gust < constant) return null; // gusts can't be lower than the constant wind
  if (gust >= 65 || constant >= 45 && gust >= 50 || constant >= 60) return "4";
  if (gust >= 50) return constant >= 45 ? "4" : "3";
  if (gust >= 40) return "2";
  return "OK";
}

