/* ---------- Live UZS/USD rate ---------- */
// Official rate from the Central Bank of Uzbekistan, refreshed every 10 minutes.
// Falls back to a second service, then to the last known rate in RATES.
const RATE_SOURCES = [
  {
    name: "Central Bank of Uzbekistan",
    url: "https://cbu.uz/uz/arkhiv-kursov-valyut/json/USD/",
    parse: (j) => ({ rate: parseFloat(j[0].Rate), change: parseFloat(j[0].Diff), date: j[0].Date.split(".").join(".") }),
  },
  {
    name: "ExchangeRate-API",
    url: "https://open.er-api.com/v6/latest/USD",
    parse: (j) => ({ rate: j.rates.UZS, change: null, date: new Date(j.time_last_update_unix * 1000).toLocaleDateString("en-GB") }),
  },
];

const FALLBACK_RATE = { rate: RATES.usdUzs, change: RATES.usdUzsChange, date: RATES.rateDate, source: "Central Bank of Uzbekistan", live: false, loading: false };
const RateContext = createContext(FALLBACK_RATE);
const useRate = () => useContext(RateContext);

function useLiveRate(refreshMs = 10 * 60 * 1000) {
  const [state, setState] = useState({ ...FALLBACK_RATE, loading: true });
  useEffect(() => {
    let alive = true;
    const load = async () => {
      for (const src of RATE_SOURCES) {
        try {
          const res = await fetch(src.url, { cache: "no-store" });
          if (!res.ok) continue;
          const r = src.parse(await res.json());
          if (!r.rate || !isFinite(r.rate)) continue;
          if (alive) setState({ ...r, source: src.name, live: true, loading: false, updated: new Date() });
          return;
        } catch { /* try next source */ }
      }
      if (alive) setState((p) => ({ ...p, loading: false }));
    };
    load();
    const t = setInterval(load, refreshMs);
    return () => { alive = false; clearInterval(t); };
  }, [refreshMs]);
  return state;
}

